// ======================== uploader/Dockerfile ========================
// # Photo-frame uploader. Node 22 is in active LTS (Node 20 reached end of life
// # in April 2026). sharp ships prebuilt musl binaries, so no compiler is needed.
// FROM node:22-alpine
// 
// ENV NODE_ENV=production
// WORKDIR /app
// 
// # Dependencies first so this layer is cached until the lockfile changes.
// COPY package.json package-lock.json ./
// RUN npm ci --omit=dev --no-audit --no-fund && npm cache clean --force
// 
// COPY src ./src
// COPY public ./public
// 
// # Runs as an unprivileged user. docker-compose.yaml overrides the uid:gid so the
// # files it writes are owned by whoever owns the photo folder on the host.
// USER node
// EXPOSE 3000
// 
// HEALTHCHECK --interval=30s --timeout=5s --start-period=15s --retries=3 \
//   CMD node -e "fetch('http://127.0.0.1:'+(process.env.PORT||3000)+'/healthz').then(r=>process.exit(r.ok?0:1)).catch(()=>process.exit(1))"
// 
// CMD ["node", "src/server.js"]
//
// ======================== uploader/docker-compose.yaml ========================
// # Photo-frame uploader: a separate service from the frame itself.
// #
// # The frame mounts /photos READ-ONLY on purpose, so a bug in the page the iPad
// # loads can never change your photos. This service is the one place that can
// # write, which is why it sits behind a password and is a second, small app.
// #
// # Coolify: create it as a second resource from the same repository with the
// # base directory set to /uploader, and give it its own domain (service port 3000).
// services:
//   photo-uploader:
//     build:
//       context: .
//     restart: unless-stopped
// 
//     # Run as the user who owns the photo folder on the host, so the files written
//     # here are readable by the frame and by you over SSH. Find it with:
//     #   stat -c '%u:%g' /srv/photos
//     user: "${UPLOAD_UID:-1000}:${UPLOAD_GID:-1000}"
// 
//     volumes:
//       - ${PHOTOS_HOST_DIR:-/srv/photos}:/photos      # read-write: this is the point
// 
//     environment:
//       PORT: "3000"
//       PHOTOS_DIR: /photos
//       TRUST_PROXY: "1"                                # Coolify's proxy is one hop in front
//       UPLOAD_PASSWORD: ${UPLOAD_PASSWORD:?set UPLOAD_PASSWORD to 12+ characters}
//       SESSION_SECRET: ${SESSION_SECRET:-}
//       SESSION_HOURS: ${SESSION_HOURS:-168}
//       MAX_UPLOAD_MB: ${MAX_UPLOAD_MB:-40}
//       MAX_EDGE: ${MAX_EDGE:-2560}
//       JPEG_QUALITY: ${JPEG_QUALITY:-82}
//       FRAME_MAX_PHOTOS_PER_ALBUM: ${FRAME_MAX_PHOTOS_PER_ALBUM:-500}   # keep equal to the frame's MAX_PHOTOS_PER_ALBUM
// 
//     # Hardening: nothing here needs to write outside /photos and /tmp.
//     read_only: true
//     tmpfs:
//       - /tmp:size=64m
//     cap_drop: [ALL]
//     security_opt:
//       - no-new-privileges:true
